css:
.loader { --accent: var(--loader-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; left: 50%; top: 6%; width: calc(var(--loader-size) * .32); height: calc(var(--loader-size) * .32); margin-left: calc(var(--loader-size) * -.16); border-radius: 50%; background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 45%, var(--accent)), var(--accent)); transform-origin: center bottom; animation: bounce calc(var(--loader-speed) * .9) cubic-bezier(.5, .05, .5, .95) infinite; }
.loader::after { content: ''; position: absolute; left: 50%; bottom: 5%; width: 46%; height: 8%; margin-left: -23%; border-radius: 50%; background: color-mix(in srgb, var(--accent) 45%, transparent); animation: shadow calc(var(--loader-speed) * .9) cubic-bezier(.5, .05, .5, .95) infinite; }
@keyframes bounce { 0%, 100% { transform: translateY(0) scale(1, 1); } 50% { transform: translateY(calc(var(--loader-size) * .55)) scale(1.18, .8); } }
@keyframes shadow { 0%, 100% { transform: scale(.55); opacity: .35; } 50% { transform: scale(1.1); opacity: .7; } }
